package com.squadsystem.squadmeasure.data

import android.content.Context
import androidx.room.withTransaction
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import com.squadsystem.squadmeasure.core.database.*
import com.squadsystem.squadmeasure.core.model.*
import com.squadsystem.squadmeasure.core.network.*
import com.squadsystem.squadmeasure.sync.SyncScheduler
import kotlinx.coroutines.flow.*
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.*
import retrofit2.HttpException
import java.time.Instant
import java.util.UUID

class SecureSessionStore(context:Context):SessionStore{private val prefs=EncryptedSharedPreferences.create(context,"measure_session",MasterKey.Builder(context).setKeyScheme(MasterKey.KeyScheme.AES256_GCM).build(),EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM);override fun accessToken()=prefs.getString("access",null);override fun refreshToken()=prefs.getString("refresh",null);override fun ownerId()=prefs.getString("owner",null);override fun save(access:String,refresh:String){prefs.edit().putString("access",access).putString("refresh",refresh).apply()};override fun saveOwner(id:String){prefs.edit().putString("owner",id).apply()};override fun clear(){prefs.edit().clear().apply()}}

interface MeasureRepository{
 val configuration:ConfigurationState
 fun visits():Flow<List<MeasureVisit>>;fun environments(visitId:String):Flow<List<EnvironmentEntity>>;fun elements(environmentId:String):Flow<List<ElementEntity>>;fun measurements(elementId:String):Flow<List<MeasurementEntity>>;fun observations(visitId:String):Flow<List<ObservationEntity>>;fun mutations():Flow<List<PendingMutationEntity>>;fun lastSync():Flow<String?>
 suspend fun login(email:String,password:String):Result<Unit>;suspend fun refresh():Result<Unit>;suspend fun loadVisit(id:String):Result<Unit>;suspend fun logout(discard:Boolean=false):Result<Unit>;suspend fun pending(visitId:String):Int
 suspend fun saveEnvironment(row:EnvironmentEntity):Result<Unit>;suspend fun saveElement(row:ElementEntity):Result<Unit>;suspend fun duplicateElement(id:String,copyStructure:Boolean):Result<String>;suspend fun saveMeasurement(row:MeasurementEntity):Result<Unit>;suspend fun saveObservation(row:ObservationEntity):Result<Unit>;suspend fun transition(visitId:String,action:String,expectedVersion:Int):Result<Unit>;suspend fun retrySync():Result<Int>
 fun ownerId():String
}

class DefaultMeasureRepository(private val context:Context,private val db:MeasureDatabase,private val session:SecureSessionStore):MeasureRepository{
 override val configuration=NetworkFactory.configuration();private val owner=MutableStateFlow(session.ownerId().orEmpty());private val api=NetworkFactory.mobile(session);private val auth=NetworkFactory.auth(session);private val dao=db.dao()
 override fun ownerId()=owner.value
 override fun visits()=owner.flatMapLatest{dao.visits(it)}.map{rows->rows.map{it.domain()}}
 override fun environments(visitId:String)=owner.flatMapLatest{dao.environments(visitId,it)}
 override fun elements(environmentId:String)=owner.flatMapLatest{dao.elements(environmentId,it)}
 override fun measurements(elementId:String)=owner.flatMapLatest{dao.measurements(elementId,it)}
 override fun observations(visitId:String)=owner.flatMapLatest{dao.observations(visitId,it)}
 override fun mutations()=owner.flatMapLatest{dao.mutations(it)}
 override fun lastSync()=owner.flatMapLatest{dao.metadataValue("lastSync:$it")}
 override suspend fun login(email:String,password:String):Result<Unit>{if(!configuration.valid)return Result.Failure(AppError.Configuration(configuration.missing));return try{val r=auth.login(mapOf("email" to email,"password" to password));session.save(r.accessToken,r.refreshToken);refresh()}catch(_:Exception){Result.Failure(AppError.AuthenticationRequired)}}
 override suspend fun refresh():Result<Unit>{if(session.accessToken()==null)return Result.Failure(AppError.AuthenticationRequired);if(!configuration.valid)return Result.Failure(AppError.Configuration(configuration.missing));return try{val b=bootstrapWithRefresh();if("*" !in b.permissions&&"squadmeasure.visualizar" !in b.permissions)Result.Failure(AppError.PermissionDenied)else{owner.value=b.user.id;session.saveOwner(owner.value);dao.upsertVisits(b.visits.map{it.entity(owner.value)});markLastSync();Result.Success(Unit)}}catch(e:Exception){if(com.squadsystem.squadmeasure.BuildConfig.DEBUG)android.util.Log.e("SquadMeasure","Bootstrap falhou: ${e::class.java.simpleName}: ${e.message}");Result.Failure(mapException(e))}}
 private suspend fun bootstrapWithRefresh():BootstrapDto=try{api.bootstrap()}catch(e:HttpException){if(e.code()!=401)throw e;val token=session.refreshToken()?:throw e;val refreshed=auth.refresh(mapOf("refresh_token" to token));session.save(refreshed.accessToken,refreshed.refreshToken);api.bootstrap()}
 override suspend fun loadVisit(id:String):Result<Unit>{if(!configuration.valid)return Result.Failure(AppError.Configuration(configuration.missing));return try{val detail=api.visit(id);persistDetail(detail);markLastSync();Result.Success(Unit)}catch(e:Exception){Result.Failure(mapException(e))}}
 override suspend fun pending(visitId:String)=dao.pendingCount(owner.value,visitId)
 override suspend fun logout(discard:Boolean):Result<Unit>{val current=owner.value;if(current.isNotBlank()&&!discard&&dao.nextMutations(current).isNotEmpty())return Result.Failure(AppError.Validation(mapOf("logout" to listOf("Existem alterações pendentes."))));session.clear();owner.value="";if(discard&&current.isNotBlank())clearOwner(current);return Result.Success(Unit)}
 private suspend fun clearOwner(id:String)=db.withTransaction{dao.clearMutations(id);dao.clearObservations(id);dao.clearMeasurements(id);dao.clearElements(id);dao.clearEnvironments(id);dao.clearVisits(id)}
 override suspend fun saveEnvironment(row:EnvironmentEntity)=save("environment",row.id,row.visitId,if(row.version==0)"CREATE" else if(row.deletedAt!=null)"ARCHIVE" else "UPDATE",row.version,environmentPayload(row)){dao.upsertEnvironment(row.pending())}
 override suspend fun saveElement(row:ElementEntity)=save("element",row.id,row.visitId,if(row.version==0)"CREATE" else if(row.deletedAt!=null)"ARCHIVE" else "UPDATE",row.version,elementPayload(row)){dao.upsertElement(row.pending())}
 override suspend fun saveMeasurement(row:MeasurementEntity)=save("measurement",row.id,row.visitId,if(row.version==0)"CREATE" else "UPDATE",row.version,measurementPayload(row)){dao.upsertMeasurement(row.pending())}
 override suspend fun saveObservation(row:ObservationEntity)=save("observation",row.id,row.visitId,if(row.version==0)"CREATE" else "UPDATE",row.version,observationPayload(row)){dao.upsertObservation(row.pending())}
 private suspend fun save(type:String,id:String,visitId:String,operation:String,version:Int,payload:JsonObject,write:suspend()->Unit):Result<Unit>{if(owner.value.isBlank())return Result.Failure(AppError.AuthenticationRequired);return try{val now=Instant.now().toString();db.withTransaction{write();dao.enqueue(PendingMutationEntity(UUID.randomUUID().toString(),owner.value,visitId,type,id,operation,payload.toString(),version.takeIf{it>0},createdAt=now))};SyncScheduler.enqueue(context);Result.Success(Unit)}catch(e:Exception){Result.Failure(AppError.Unknown(e))}}
 override suspend fun duplicateElement(id:String,copyStructure:Boolean):Result<String>{val source=dao.element(id,owner.value)?:return Result.Failure(AppError.NotFound);val newId=UUID.randomUUID().toString();val now=Instant.now().toString();val copy=source.copy(id=newId,name="${source.name} (cópia)",version=0,createdAt=now,updatedAt=now,syncState=SyncState.PENDING.name,lastSyncAt=null);val saved=saveElement(copy);if(saved is Result.Failure)return saved;if(copyStructure){dao.measurements(source.id,owner.value).first().forEach{m->saveMeasurement(m.copy(id=UUID.randomUUID().toString(),elementId=newId,value=0.0,state="provisoria",version=0,createdAt=now,updatedAt=now,syncState=SyncState.PENDING.name,lastSyncAt=null))}};return Result.Success(newId)}
 override suspend fun transition(visitId:String,action:String,expectedVersion:Int):Result<Unit>{if(pending(visitId)>0)return Result.Failure(AppError.Validation(mapOf("sync" to listOf("Sincronize as alterações antes de enviar para revisão."))));return try{val response=api.transition(visitId,buildJsonObject{put("action",action);put("expectedVersion",expectedVersion)});if(response.isSuccessful){refresh();Result.Success(Unit)}else Result.Failure(mapResponse(response.code(),response.errorBody()?.string()))}catch(e:Exception){Result.Failure(mapException(e))}}
 override suspend fun retrySync():Result<Int>{val current=owner.value;if(current.isBlank()||session.ownerId()!=current)return Result.Failure(AppError.AuthenticationRequired);var sent=0;for(m in dao.nextMutations(current)){if(!parentReady(m))continue;dao.mutationState(m.id,"SYNCING",0,Instant.now().toString(),null,null);setEntitySync(m,SyncState.SYNCING,0,null);try{val body=NetworkFactory.json.parseToJsonElement(m.payload).jsonObject;val response=when(m.entityType){"environment"->if(m.operation=="CREATE")api.createEnvironment(body)else api.updateEnvironment(body);"element"->if(m.operation=="CREATE")api.createElement(body)else api.updateElement(body);"measurement"->if(m.operation=="CREATE")api.createMeasurement(body)else api.updateMeasurement(body);else->if(m.operation=="CREATE")api.createObservation(body)else api.updateObservation(body)};if(response.isSuccessful){val version=response.body()?.version?:1;setEntitySync(m,SyncState.SYNCED,version,null);dao.deleteMutation(m.id);sent++}else{val error=mapResponse(response.code(),response.errorBody()?.string());val state=if(error is AppError.VersionConflict)SyncState.CONFLICT else SyncState.ERROR;setEntitySync(m,state,0,error);dao.mutationState(m.id,state.name,1,Instant.now().toString(),error.code(),error.message())}}catch(e:Exception){val error=mapException(e);setEntitySync(m,SyncState.ERROR,0,error);dao.mutationState(m.id,"ERROR",1,Instant.now().toString(),error.code(),error.message())}}
  if(sent>0)markLastSync();return Result.Success(sent)}
 private suspend fun parentReady(m:PendingMutationEntity)=when(m.entityType){"element"->NetworkFactory.json.parseToJsonElement(m.payload).jsonObject["ambiente_id"]?.jsonPrimitive?.content?.let{dao.environment(it,owner.value)?.syncState==SyncState.SYNCED.name}?:false;"measurement"->NetworkFactory.json.parseToJsonElement(m.payload).jsonObject["elemento_id"]?.jsonPrimitive?.content?.let{dao.element(it,owner.value)?.syncState==SyncState.SYNCED.name}?:false;else->true}
 private suspend fun setEntitySync(m:PendingMutationEntity,state:SyncState,version:Int,error:AppError?){val now=Instant.now().toString();val current=when(m.entityType){"environment"->dao.environment(m.entityId,owner.value)?.version;"element"->dao.element(m.entityId,owner.value)?.version;"measurement"->dao.measurement(m.entityId,owner.value)?.version;else->dao.observation(m.entityId,owner.value)?.version}?:0;val v=if(version>0)version else current;when(m.entityType){"environment"->dao.environmentSync(m.entityId,state.name,v,if(state==SyncState.SYNCED)now else null,error?.code(),error?.message());"element"->dao.elementSync(m.entityId,state.name,v,if(state==SyncState.SYNCED)now else null,error?.code(),error?.message());"measurement"->dao.measurementSync(m.entityId,state.name,v,if(state==SyncState.SYNCED)now else null,error?.code(),error?.message());else->dao.observationSync(m.entityId,state.name,v,if(state==SyncState.SYNCED)now else null,error?.code(),error?.message())}}
 private suspend fun markLastSync(){dao.metadata(MetadataEntity("lastSync:${owner.value}",Instant.now().toString()))}
 private suspend fun persistDetail(root:JsonObject){val now=Instant.now().toString();val visitId=root.text("id");for(e in root.array("ambientes")){val env=e.jsonObject;val envId=env.text("id");dao.upsertEnvironment(EnvironmentEntity(envId,owner.value,visitId,env.text("nome"),env.nullText("codigo"),env.nullText("pavimento"),env.nullText("descricao"),env.int("sequencia"),env.text("status"),env.nullText("observacoes"),1,now,now,env.nullText("arquivado_em"),SyncState.SYNCED.name,now));for(x in env.array("elementos")){val el=x.jsonObject;val elId=el.text("id");dao.upsertElement(ElementEntity(elId,owner.value,visitId,envId,el.text("nome"),el.nullText("codigo"),el.text("tipo"),el.int("quantidade"),el.nullText("descricao"),el.int("sequencia"),el.text("status"),el.bool("requer_atencao"),version=1,createdAt=now,updatedAt=now,deletedAt=el.nullText("arquivado_em"),syncState=SyncState.SYNCED.name,lastSyncAt=now));for(y in el.array("medidas")){val me=y.jsonObject;dao.upsertMeasurement(MeasurementEntity(me.text("id"),owner.value,visitId,elId,me.nullText("grupo"),me.text("tipo"),me.text("nome"),me.nullText("posicao"),me.double("valor"),me.text("unidade"),me.nullDouble("tolerancia"),me.text("estado"),me.nullText("observacao"),me.text("origem"),me.nullText("medida_em")?:now,1,now,now,syncState=SyncState.SYNCED.name,lastSyncAt=now))}}};for(o in root.array("observacoes")){val ob=o.jsonObject;dao.upsertObservation(ObservationEntity(ob.text("id"),owner.value,visitId,ob.nullText("ambiente_id"),ob.nullText("elemento_id"),ob.nullText("medida_id"),ob.text("categoria"),ob.text("texto"),ob.bool("importante"),resolvedAt=ob.nullText("resolvida_em"),version=1,createdAt=ob.nullText("criado_em")?:now,updatedAt=now,syncState=SyncState.SYNCED.name,lastSyncAt=now))}}
}

private fun VisitEntity.domain()=MeasureVisit(id,workId,workName,clientName,address,responsibleName,VisitStatus.valueOf(status),VisitPriority.valueOf(priority),scheduledAt,progress,notes,version,SyncState.valueOf(syncState))
private fun VisitDto.entity(owner:String)=VisitEntity(id,owner,workId,workName,clientName,address,responsibleName,status.name,priority.name,scheduledAt,progress,notes,version,SyncState.SYNCED.name,Instant.now().toString())
private fun EnvironmentEntity.pending()=copy(updatedAt=Instant.now().toString(),syncState=if(deletedAt==null)SyncState.PENDING.name else SyncState.DELETED_PENDING.name,lastErrorCode=null,lastErrorMessage=null)
private fun ElementEntity.pending()=copy(updatedAt=Instant.now().toString(),syncState=if(deletedAt==null)SyncState.PENDING.name else SyncState.DELETED_PENDING.name,lastErrorCode=null,lastErrorMessage=null)
private fun MeasurementEntity.pending()=copy(updatedAt=Instant.now().toString(),syncState=SyncState.PENDING.name,lastErrorCode=null,lastErrorMessage=null)
private fun ObservationEntity.pending()=copy(updatedAt=Instant.now().toString(),syncState=SyncState.PENDING.name,lastErrorCode=null,lastErrorMessage=null)
private fun environmentPayload(x:EnvironmentEntity)=buildJsonObject{put("id",x.id);put("visita_id",x.visitId);put("nome",x.name);x.code?.let{put("codigo",it)};x.floor?.let{put("pavimento",it)};x.description?.let{put("descricao",it)};put("sequencia",x.sequence);put("status",x.status);x.notes?.let{put("observacoes",it)};if(x.version>0)put("expectedVersion",x.version);if(x.deletedAt!=null)put("arquivado",true)}
private fun elementPayload(x:ElementEntity)=buildJsonObject{put("id",x.id);put("ambiente_id",x.environmentId);put("nome",x.name);x.code?.let{put("codigo",it)};put("tipo",x.type);put("quantidade",x.quantity);x.description?.let{put("descricao",it)};put("sequencia",x.sequence);put("status",x.status);put("requer_atencao",x.attention);if(x.version>0)put("expectedVersion",x.version);if(x.deletedAt!=null)put("arquivado",true)}
private fun measurementPayload(x:MeasurementEntity)=buildJsonObject{put("id",x.id);put("elemento_id",x.elementId);x.groupName?.let{put("grupo",it)};put("tipo",x.type);put("nome",x.name);x.position?.let{put("posicao",it)};put("valor",x.value);put("unidade",x.unit);x.tolerance?.let{put("tolerancia",it)};put("estado",x.state);x.note?.let{put("observacao",it)};put("origem",x.origin);put("medida_em",x.measuredAt);if(x.version>0)put("expectedVersion",x.version)}
private fun observationPayload(x:ObservationEntity)=buildJsonObject{put("id",x.id);put("visita_id",x.visitId);x.environmentId?.let{put("ambiente_id",it)};x.elementId?.let{put("elemento_id",it)};x.measurementId?.let{put("medida_id",it)};put("categoria",x.category);put("texto",x.text);put("importante",x.important);if(x.version>0){put("expectedVersion",x.version);put("resolvida",x.resolvedAt!=null)}}
private fun JsonObject.text(k:String)=getValue(k).jsonPrimitive.content;private fun JsonObject.nullText(k:String)=get(k)?.jsonPrimitive?.contentOrNull;private fun JsonObject.int(k:String)=getValue(k).jsonPrimitive.int;private fun JsonObject.double(k:String)=getValue(k).jsonPrimitive.double;private fun JsonObject.nullDouble(k:String)=get(k)?.jsonPrimitive?.doubleOrNull;private fun JsonObject.bool(k:String)=getValue(k).jsonPrimitive.boolean;private fun JsonObject.array(k:String)=get(k)?.jsonArray?:JsonArray(emptyList())
private fun mapResponse(code:Int,body:String?):AppError{val key=runCatching{body?.let{NetworkFactory.json.parseToJsonElement(it).jsonObject["code"]?.jsonPrimitive?.content}}.getOrNull();return when(key){"AUTH_REQUIRED"->AppError.AuthenticationRequired;"USER_NOT_FOUND"->AppError.UserNotFound;"PERMISSION_DENIED"->AppError.PermissionDenied;"ENTITY_NOT_FOUND"->AppError.NotFound;"INVALID_STATUS_TRANSITION"->AppError.InvalidStatusTransition;"ENTITY_LOCKED"->AppError.EntityLocked;"VERSION_CONFLICT"->AppError.VersionConflict();"VALIDATION_ERROR"->AppError.Validation(emptyMap());"RLS_DENIED"->AppError.RlsDenied;"DATABASE_ERROR"->AppError.Database;else->if(code==401)AppError.AuthenticationRequired else AppError.ServerUnavailable}}
private fun mapException(e:Exception)=when(e){is HttpException->mapResponse(e.code(),e.response()?.errorBody()?.string());is java.io.IOException->AppError.NetworkUnavailable;else->AppError.Unknown(e)}
private fun AppError.code()=this::class.simpleName?:"UNKNOWN_ERROR";private fun AppError.message()=when(this){AppError.AuthenticationRequired->"Sua sessão expirou. Entre novamente.";AppError.PermissionDenied->"Você não possui permissão para esta ação.";is AppError.VersionConflict->"A visita foi alterada em outro dispositivo.";AppError.EntityLocked->"Esta medição já foi encerrada.";AppError.NetworkUnavailable->"Não foi possível enviar agora. O dado permanece salvo no aparelho.";else->"Não foi possível concluir a operação."}
class AppContainer(context:Context){val session=SecureSessionStore(context);val database=MeasureDatabase.create(context);val repository:MeasureRepository=DefaultMeasureRepository(context,database,session);init{SyncScheduler.periodic(context)}}
